CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE members(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),full_name varchar(160) NOT NULL,nickname varchar(80),email varchar(254) UNIQUE,mobile varchar(40),location varchar(120),preferred_position varchar(40),skill_level varchar(30),joined_on date,active boolean NOT NULL DEFAULT true);
CREATE TABLE teams(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(160) NOT NULL UNIQUE,short_name varchar(30) NOT NULL UNIQUE,description text,primary_color varchar(20),secondary_color varchar(20),founded_on date,active boolean NOT NULL DEFAULT true);
CREATE TABLE team_members(team_id uuid NOT NULL REFERENCES teams,member_id uuid NOT NULL REFERENCES members,role varchar(30) NOT NULL DEFAULT 'PLAYER',joined_at timestamptz NOT NULL DEFAULT now(),left_at timestamptz,PRIMARY KEY(team_id,member_id,joined_at));
CREATE TABLE matches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),version bigint NOT NULL DEFAULT 0,match_number bigint NOT NULL UNIQUE,title varchar(180) NOT NULL,type varchar(40),status varchar(40),starts_at timestamptz,ends_at timestamptz,maximum_players integer NOT NULL CHECK(maximum_players>0),registration_fee numeric(12,2),currency char(3) NOT NULL DEFAULT 'QAR');
CREATE TABLE match_registrations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),match_id uuid NOT NULL REFERENCES matches,member_id uuid NOT NULL REFERENCES members,status varchar(30) NOT NULL,registered_at timestamptz NOT NULL,waitlist_position integer,UNIQUE(match_id,member_id));
CREATE INDEX idx_reg_queue ON match_registrations(match_id,status,registered_at);
